from flask import Blueprint, jsonify

routes = Blueprint('routes', __name__)

@routes.route('/problems', methods=['GET'])
def get_problems():
    # This would typically fetch data from the database
    # Since no database is specified, returning a placeholder response
    return jsonify({"message": "List of problems"}), 200

@routes.route('/submit', methods=['POST'])
def submit_code():
    # Placeholder for code submission endpoint
    return jsonify({"message": "Code submission endpoint"}), 200

@routes.route('/leaderboard', methods=['GET'])
def get_leaderboard():
    # Placeholder for leaderboard data
    return jsonify({"message": "Leaderboard data"}), 200

/* Path: static/style.css */
/* Purpose: Stylesheet for ACM Problem-Solving Platform */

/* General Reset */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    font-family: Arial, sans-serif;
    background-color: #f9f9f9;
    color: #333;
    line-height: 1.6;
    padding: 0;
    margin: 0;
}

/* Header Styling */
header {
    background: #0078d7;
    color: #fff;
    padding: 20px 0;
    text-align: center;
}

header h1 {
    margin: 0;
}

/* Navigation Bar */
nav {
    display: flex;
    justify-content: center;
    background: #005ea6;
}

nav a {
    color: white;
    padding: 15px 20px;
    text-decoration: none;
    font-weight: bold;
}

nav a:hover {
    background: #004080;
}

/* Main Content Styling */
main {
    max-width: 1200px;
    margin: 20px auto;
    padding: 20px;
    background: white;
    border-radius: 5px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

/* Footer Styling */
footer {
    background: #0078d7;
    color: white;
    text-align: center;
    padding: 10px 0;
    position: fixed;
    bottom: 0;
    width: 100%;
}

/* Problem List Styles */
.problem-list {
    list-style: none;
    padding: 0;
}

.problem-list li {
    padding: 10px;
    border-bottom: 1px solid #ddd;
}

.problem-list li:last-child {
    border-bottom: none;
}

.problem-list li a {
    text-decoration: none;
    color: #0078d7;
}

.problem-list li a:hover {
    text-decoration: underline;
}

/* Leaderboard Styles */
.leaderboard {
    margin-top: 20px;
    border-collapse: collapse;
    width: 100%;
}

.leaderboard th,
.leaderboard td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
}

.leaderboard th {
    background-color: #0078d7;
    color: white;
}

.leaderboard tr:nth-child(even) {
    background-color: #f2f2f2;
}

.leaderboard tr:hover {
    background-color: #ddd;
}

/* Button Styles */
.button {
    display: inline-block;
    padding: 10px 20px;
    background: #0078d7;
    color: white;
    text-decoration: none;
    border-radius: 5px;
    font-weight: bold;
    text-align: center;
}

.button:hover {
    background: #005ea6;
}

/* Form Styles */
form {
    margin-top: 20px;
}

form input[type="text"],
form input[type="email"],
form input[type="password"],
form textarea {
    width: 100%;
    padding: 10px;
    margin-bottom: 10px;
    border: 1px solid #ccc;
    border-radius: 5px;
}

form input[type="submit"] {
    background: #0078d7;
    color: white;
    padding: 10px 15px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
}

form input[type="submit"]:hover {
    background: #005ea6;
}

/* User Profile Styles */
.profile {
    display: flex;
    align-items: center;
    gap: 20px;
    margin-top: 20px;
}

.profile img {
    border-radius: 50%;
    width: 100px;
    height: 100px;
    object-fit: cover;
}

.profile-info {
    flex: 1;
}

.profile-info h2 {
    margin-bottom: 10px;
}

.profile-info p {
    margin-bottom: 5px;
    color: #555;
}

